css:
@font-face{font-family:'Slab';src:url(node_modules/@fontsource/alfa-slab-one/files/alfa-slab-one-latin-400-normal.woff2);}
@font-face{font-family:'Frank';src:url(node_modules/@fontsource/libre-franklin/files/libre-franklin-latin-500-normal.woff2);font-weight:500;}
@font-face{font-family:'Frank';src:url(node_modules/@fontsource/libre-franklin/files/libre-franklin-latin-800-normal.woff2);font-weight:800;}
@font-face{font-family:'Type';src:url(node_modules/@fontsource/courier-prime/files/courier-prime-latin-700-normal.woff2);font-weight:700;}
.card{background:#E3A72F;color:#2A2118;font-family:'Frank';font-weight:500;}
.card::before{content:'';position:absolute;inset:0;background-image:radial-gradient(#2A211833 3px,transparent 3.5px);background-size:22px 22px;}
.page{position:absolute;inset:150px 50px 330px 50px;background:#F4E9CF;border:8px solid #2A2118;box-shadow:16px 16px 0 #5B6236;}
/*h*/.head{position:absolute;top:180px;left:90px;right:150px;display:flex;justify-content:space-between;font:700 34px 'Type';color:#2A2118;border-bottom:5px solid #2A2118;padding-bottom:14px;z-index:2;}
.safe{padding-left:30px;padding-right:20px;inset:270px 140px 440px 80px;}
.tag{display:inline-block;align-self:flex-start;background:#5B6236;color:#F4E9CF;font:700 44px 'Type';padding:10px 24px;margin-bottom:40px;}
h1{font-family:'Slab';font-weight:400;font-size:116px;line-height:1.02;margin:0;}
h2{font-family:'Slab';font-weight:400;font-size:112px;line-height:1.02;margin:0 0 34px;color:#C4561E;}
.big{font-family:'Slab';font-size:150px;line-height:1;margin:0 0 30px;color:#C4561E;}
p.b{font-size:54px;line-height:1.28;margin:0 0 30px;}
p.b strong,.em{font-weight:800;}
.hl{background:linear-gradient(transparent 55%,#E3A72F 55%);}
.row{display:flex;gap:30px;align-items:baseline;border-top:5px solid #2A2118;padding:24px 0;}
.row b{font-family:'Slab';font-weight:400;font-size:84px;min-width:220px;color:#C4561E;}
.row span{font-size:52px;line-height:1.25;}
.card-1{background:#C4561E;}
.card-1 .page{background:#C4561E;border-color:#F4E9CF;box-shadow:16px 16px 0 #2A2118;}
.card-1 /*h*/.head{color:#F4E9CF;border-color:#F4E9CF;}
.card-1 h1{color:#F4E9CF;}
.card-1 .kick{font:700 48px 'Type';color:#2A2118;background:#E3A72F;align-self:flex-start;padding:10px 22px;margin-bottom:44px;}
.pair{display:flex;flex-direction:column;gap:30px;}
.box{border:6px solid #2A2118;padding:26px 30px;background:#FFF8E6;}
.box .n{font-family:'Slab';font-size:92px;line-height:1;}
.box .d{font-size:52px;margin-top:10px;}
.up .n{color:#C4561E;} .down .n{color:#5B6236;}
.end h1{font-size:118px;color:#C4561E;}
.end p.b{margin-top:40px;}
.handle{font:700 58px 'Type';margin-top:30px;background:#2A2118;color:#F4E9CF;align-self:flex-start;padding:14px 26px;}

.head::before{content:'CH. 7 · THE PANCREAS';}
.gl{font-family:'Slab';font-size:76px;line-height:1.1;margin:10px 0 0;border-top:5px solid #2A2118;padding-top:26px;} .gl i{font-style:normal;color:#5B6236;}
.row.n b{min-width:90px;}
p.b{font-size:58px;}
.card-1 .head::after{content:'1/6';}
.card-2 .head::after{content:'2/6';}
.card-3 .head::after{content:'3/6';}
.card-4 .head::after{content:'4/6';}
.card-5 .head::after{content:'5/6';}
.card-6 .head::after{content:'6/6';}
.pair{width:100%;} .box{width:100%;} .box .d{font-size:56px;}
